svg.script:

(function() {
  var currentLevel = 0;

  var levelYMap = {
    '-3': 132,
    '-2': 162,
    '-1': 192,
    '0': 222,
    '1': 252,
    '2': 282,
    '3': 312
  };

  window.a12p12hSetLevel = function(lvl) {
    currentLevel = lvl;

    var headEl = document.getElementById('a12p12h-fetal-head');
    if (headEl && levelYMap[lvl] !== undefined) {
      headEl.setAttribute('transform', 'translate(240, ' + levelYMap[lvl] + ')');
    }

    var highlights = ['m3', 'm2', 'm1', '0', 'p1', 'p2', 'p3'];
    highlights.forEach(function(h) {
      var el = document.getElementById('a12p12h-hl-' + h);
      if (el) el.setAttribute('opacity', '0');
    });
    var targetHlId = (lvl < 0) ? 'm' + Math.abs(lvl) : (lvl === 0 ? '0' : 'p' + lvl);
    var activeHl = document.getElementById('a12p12h-hl-' + targetHlId);
    if (activeHl) activeHl.setAttribute('opacity', '0.4');

    var btnM1 = document.getElementById('a12p12h-btn-m1');
    var btn0 = document.getElementById('a12p12h-btn-0');
    var btnP1 = document.getElementById('a12p12h-btn-p1');

    if (btnM1) btnM1.classList.remove('a12p12h-active');
    if (btn0) btn0.classList.remove('a12p12h-active');
    if (btnP1) btnP1.classList.remove('a12p12h-active');

    if (lvl === -1 && btnM1) btnM1.classList.add('a12p12h-active');
    if (lvl === 0 && btn0) btn0.classList.add('a12p12h-active');
    if (lvl === 1 && btnP1) btnP1.classList.add('a12p12h-active');

    var lbl3Box = document.getElementById('a12p12h-lbl3-box');
    var lbl3Text = document.getElementById('a12p12h-lbl3-text');

    if (lvl >= 1) {
      if (lbl3Box) lbl3Box.setAttribute('stroke', 'var(--a12p12h-green, #10b981)');
      if (lbl3Text) {
        lbl3Text.textContent = '3. Estado: INSINUADA (+' + lvl + ' cm)';
        lbl3Text.setAttribute('fill', 'var(--a12p12h-green, #10b981)');
      }
    } else if (lvl === 0) {
      if (lbl3Box) lbl3Box.setAttribute('stroke', 'var(--a12p12h-yellow, #f59e0b)');
      if (lbl3Text) {
        lbl3Text.textContent = '3. Estado: No Gargalo (0 cm)';
        lbl3Text.setAttribute('fill', 'var(--a12p12h-yellow, #f59e0b)');
      }
    } else {
      if (lbl3Box) lbl3Box.setAttribute('stroke', 'var(--a12p12h-rose, #f43f5e)');
      if (lbl3Text) {
        lbl3Text.textContent = '3. Estado: Alta / Não Insinuada';
        lbl3Text.setAttribute('fill', 'var(--a12p12h-rose, #f43f5e)');
      }
    }

    var badgeBg = document.getElementById('a12p12h-status-badge-bg');
    var badgeText = document.getElementById('a12p12h-status-badge-text');
    var card1 = document.getElementById('a12p12h-card1-text');
    var card2 = document.getElementById('a12p12h-card2-text');

    if (lvl >= 1) {
      if (badgeBg) {
        badgeBg.setAttribute('class', 'a12p12h-badge-bg a12p12h-badge-bg-green');
      }
      if (badgeText) {
        badgeText.setAttribute('class', 'a12p12h-badge-text a12p12h-badge-text-green');
        badgeText.textContent = 'ESTÁGIO: +' + lvl + ' CM (INSINUADA / ENGAJADA)';
      }

      if (card1) {
        card1.innerHTML =
          '<tspan x="14" dy="0" font-weight="700" fill="var(--a12p12h-green, #10b981)">• DBP ultrapassou as espinhas!</tspan>' +
          '<tspan x="14" dy="16">• O maior diâmetro da cabeça (DBP 9,5 cm)</tspan>' +
          '<tspan x="14" dy="16">  já venceu o gargalo ósseo (biespinhal 10,5 cm).</tspan>';
      }

      if (card2) {
        card2.innerHTML =
          '<tspan x="14" dy="0" font-weight="700" fill="var(--a12p12h-green, #10b981)">• DIAGNÓSTICO: APRESENTAÇÃO INSINUADA</tspan>' +
          '<tspan x="14" dy="16">  Em +' + lvl + ' cm de De Lee, o feto superou a menor</tspan>' +
          '<tspan x="14" dy="16">  estrangulação da pelve. Risco de desproporção</tspan>' +
          '<tspan x="14" dy="16">  céfalo-pélvica (DCP) no estreito médio AFASTADO.</tspan>';
      }

    } else if (lvl === 0) {
      if (badgeBg) {
        badgeBg.setAttribute('class', 'a12p12h-badge-bg a12p12h-badge-bg-yellow');
      }
      if (badgeText) {
        badgeText.setAttribute('class', 'a12p12h-badge-text a12p12h-badge-text-yellow');
        badgeText.textContent = 'ESTÁGIO: DE LEE 0 CM (NO GARGALO)';
      }

      if (card1) {
        card1.innerHTML =
          '<tspan x="14" dy="0">• Polo cefálico no nível da linha biespinhal.</tspan>' +
          '<tspan x="14" dy="16">• O diâmetro biparietal (DBP) aborda o menor</tspan>' +
          '<tspan x="14" dy="16">  estreito ósseo (diâmetro biespinhal = 10,5 cm).</tspan>';
      }

      if (card2) {
        card2.innerHTML =
          '<tspan x="14" dy="0" font-weight="700" fill="var(--a12p12h-yellow, #f59e0b)">• Transição do Gargalo:</tspan>' +
          '<tspan x="14" dy="16">  O polo cefálico atinge o nível 0, mas a maior</tspan>' +
          '<tspan x="14" dy="16">  circunferência transversal ainda está completando</tspan>' +
          '<tspan x="14" dy="16">  a passagem pelo plano biespinhal.</tspan>';
      }

    } else {
      if (badgeBg) {
        badgeBg.setAttribute('class', 'a12p12h-badge-bg a12p12h-badge-bg-yellow');
      }
      if (badgeText) {
        badgeText.setAttribute('class', 'a12p12h-badge-text a12p12h-badge-text-yellow');
        badgeText.textContent = 'ESTÁGIO: ' + lvl + ' CM (NÃO INSINUADA / ALTA)';
      }

      if (card1) {
        card1.innerHTML =
          '<tspan x="14" dy="0" font-weight="700" fill="var(--a12p12h-rose, #f43f5e)">• DBP acima das espinhas isquiáticas.</tspan>' +
          '<tspan x="14" dy="16">• A maior circunferência fetal ainda não entrou</tspan>' +
          '<tspan x="14" dy="16">  no menor diâmetro transversal da pelve.</tspan>';
      }

      if (card2) {
        card2.innerHTML =
          '<tspan x="14" dy="0" font-weight="700" fill="var(--a12p12h-rose, #f43f5e)">• DIAGNÓSTICO: APRESENTAÇÃO ALTA / MÓVEL</tspan>' +
          '<tspan x="14" dy="16">  A cabeça fetal está acima do plano biespinhal.</tspan>' +
          '<tspan x="14" dy="16">  Não é possível confirmar insinuação antes</tspan>' +
          '<tspan x="14" dy="16">  de ultrapassar a linha de De Lee 0.</tspan>';
      }
    }
  };
})();
